import { html } from 'common-tags'

export const registryItem = {
  type: 'registry:ui',
  name: 'accordion',
  title: 'Accordion',

  description: html`
    A vertically stacked set of interactive headings that each reveal a section of content.

    References:
    - Headless API: https://ark-ui.com/docs/components/accordion
    - shadcn/ui: https://ui.shadcn.com/docs/components/accordion
  `,

  dependencies: [
    '@ark-ui/vue',
    '@vueuse/core',
    'lucide-vue-next',
  ],

  cssVars: {
    theme: {
      '--animate-accordion-down': 'accordion-down 0.25s ease-out',
      '--animate-accordion-up': 'accordion-up 0.25s ease-out',
    },
  },

  css: {
    '@keyframes accordion-down': {
      from: { height: '0' },
      to: { height: 'var(--height)' },
    },
    '@keyframes accordion-up': {
      from: { height: 'var(--height)' },
      to: { height: '0' },
    },
  },
}

export default registryItem

import type { Meta, StoryObj } from '@storybook/vue3-vite'

import { html } from 'common-tags'

import {
  AccordionContent,
  AccordionItem,
  AccordionRoot,
  AccordionTrigger,
} from '@/components/ui/accordion'
import { registryItem } from './_registry'

import AccordionDefault from './AccordionDefaultStory.vue'
import AccordionDefaultSource from './AccordionDefaultStory.vue?raw'

const meta = {
  title: 'Components/UI/Accordion',
  component: AccordionRoot,
  subcomponents: {
    AccordionItem,
    AccordionTrigger,
    AccordionContent,
  },
  tags: ['autodocs'],
  parameters: {
    docs: {
      description: {
        component: registryItem.description,
      },
    },
  },
} satisfies Meta<typeof AccordionRoot>

export default meta
type Story = StoryObj<typeof meta>

export const Default: Story = {
  parameters: {
    docs: {
      source: {
        code: AccordionDefaultSource,
      },
    },
  },

  render: args => ({
    components: { AccordionDefault },

    setup() {
      return { args }
    },

    template: html`
      <AccordionDefault v-bind="args" />
    `,
  }),
}
